mapper.select:
SELECT 
  FROM place p
 WHERE p.place_id = #{placeId}

mapper.update:
UPDATE place
   SET is_active  = FALSE,
       deleted_at = #{deletedAt},
       updated_at = #{deletedAt}
 WHERE place_id   = #{placeId}
   AND is_active  = TRUE

UPDATE place
   SET is_active  = TRUE,
       deleted_at = NULL,
       updated_at = #{updatedAt}
 WHERE place_id   = #{placeId}
   AND is_active  = FALSE
